import * as T from './vendor/three.module.js';
import {blocked} from './logic.mjs';
export function createForestFoxes(scene,height,colliders,animated){
 const coat=new T.MeshStandardMaterial({color:'#a86c3e',roughness:1}),cream=new T.MeshStandardMaterial({color:'#d9d0b7',roughness:1}),dark=new T.MeshStandardMaterial({color:'#3e3932',roughness:1});
 for(let i=0;i<2;i++){const g=new T.Group();g.userData.kind='alpine-red-fox';scene.add(g);function oval(m,x,y,z,sx,sy,sz,p=g){const o=new T.Mesh(new T.SphereGeometry(1,16,10),m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;p.add(o);return o;}oval(coat,0,.48,0,.17,.2,.42);oval(cream,0,.51,.24,.16,.2,.14);oval(coat,0,.76,.35,.14,.16,.18);oval(cream,0,.69,.49,.095,.07,.19);oval(dark,0,.72,.65,.035,.025,.03);for(const side of[-1,1]){const ear=new T.Mesh(new T.ConeGeometry(.075,.2,10),coat);ear.position.set(side*.1,.94,.31);ear.rotation.z=-side*.18;g.add(ear);oval(dark,side*.11,.78,.47,.015,.018,.012);}const legs=[];for(const x of[-.11,.11])for(const z of[-.27,.26]){const leg=new T.Group();leg.position.set(x,.42,z);g.add(leg);oval(coat,0,-.1,0,.04,.13,.045,leg);oval(dark,0,-.29,.02,.025,.12,.032,leg);oval(dark,0,-.4,.06,.034,.026,.06,leg);legs.push(leg);}const tail=new T.Group();g.add(tail);tail.position.set(0,.45,-.3);const brush=oval(coat,0,-.05,-.26,.105,.1,.31,tail);brush.rotation.x=-.16;oval(cream,0,-.1,-.53,.067,.07,.13,tail);let x=-30-i*6,z=-18-i*16,previous=0;g.position.set(x,height(x,z),z);animated.push(t=>{const dt=Math.min(.05,Math.max(0,t-previous));previous=t;const a=t*.13+i*2.4,nx=x+Math.cos(a)*dt*.3,nz=z+Math.sin(a)*dt*.3,moving=!blocked(nx,nz,colliders,.2);if(moving){x=nx;z=nz;}g.position.set(x,height(x,z),z);g.rotation.y=Math.PI/2-a;legs.forEach((l,k)=>l.rotation.x=moving?Math.sin(t*5+k*Math.PI)*.3:0);tail.rotation.y=Math.sin(t*.7)*.12;});}
 if(scene.userData.fauna)scene.userData.fauna.foxes=2;
}
